**Recommended Solution:**
```javascript
const express = require('express');
const morgan = require('morgan');

const app = express();

// Request logging
app.use(morgan('combined'));

// Error handling middleware MUST come after all routes
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Don't expose error details in production
  const isProduction = process.env.NODE_ENV === 'production';
  const errorResponse = isProduction ? 
    { error: 'Something went wrong' } : 
    { error: err.message, stack: err.stack };

  const statusCode = err.status || 500;

  res.status(statusCode).json(errorResponse);
});

// Handle JSON syntax errors
app.use(express.json({ 
  strict: true,
  limit: '10kb' // Prevent DoS via large payloads
}));

app.use(express.urlencoded({ extended: false }));

const requestLogger = (req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info(`${req.method} ${req.path} - ${res.statusCode} - ${duration}ms`);
  });

  next();
};

app.use(requestLogger);

const VALID_ROUTES = {
  '/health': 'GET',
  '/users': 'GET',
  '/users': 'POST',
  '/users/:id': ['GET', 'PUT', 'DELETE']
};

app.use((req, res, next) => {
  const path = req.path;
  const method = req.method;
  const allowedMethods = VALID_ROUTES[path] || [];

  if (allowedMethods.length > 0 && !allowedMethods.includes(method)) {
    return res.status(405).json({
      error: 'Method not allowed',
      availableMethods: allowedMethods,
      path: path
    });
  }

  // Verify route exists
  if (typeof VALID_ROUTES[path] !== 'undefined') {
    return res.status(404).json({
      error: 'Route not found',
      path: path,
      method: method
    });
  }

  next();
});

try {
  app.listen(parseInt(process.env.PORT) || 3000, () => {
    logger.info(`Server starting on port 3000 - Environment: ${process.env.NODE_ENV || 'development'}`);
  });
} catch (error) {
  logger.error('Failed to start server', { error: error.message });
  process.exit(1);
}
