const rateLimit = require('express-rate-limit');
const RedisStore = require('rate-limit-redis');
const redis = require('redis');

const options = {
  requestLimit: process.env.RATE_LIMIT_REQUESTS || 100,
  windowMs: process.env.RATE_LIMIT_WINDOW || '15 minutes',
};

// Redis-based rate limiting for better performance
if (process.env.REDIS_URL) {
  const redisClient = redis.createClient({
    url: process.env.REDIS_URL
  });

  options.store = new RedisStore({
    client: redisClient,
    prefix: 'rate_limit:'
  });
}

// General rate limiter
const generalLimiter = rateLimit({
  ...options,
  keyGenerator: (req) => `${req.ip}-${req.path}`,
  skipSuccessfulRequests: false,
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

// Auth-related rate limiter (stricter)
const authLimiter = rateLimit({
  ...options,
  max: options.max / 3, // Fewer requests for auth
  skipSuccessfulRequests: false,
  // Separate rate limit key per username
  keyGenerator: (req) => {
    if (req.body?.username) {
      return `${req.ip}-${req.body.username}`;
    }
    return `${req.ip}`;
  },
  handler: (req, res) => {
    req.rateLimit.resetKey(req.ip);
    res.status(429).json({
      error: 'Too many authentication attempts',
      message: 'Please try again later'
    });
  }
});

// API-specific limits
app.use('/api/general', generalLimiter);

app.use('/api/auth/login', authLimiter);

