  upload.single('file'),
  (req, res) => {
    // Handle file upload
  }
);

// IP-based ban for repeated failures
const ipBanLimiter = rateLimit({
  max: 3, // 3 requests before moving to IP-specific limiting
  keyGenerator: (req) => req.ip,
  skipSuccessfulRequests: true,
  handler: (req, res) => {
    logger.warn(`IP ${req.ip} rate limit exceeded after ${req.rateLimit.limit} requests`);

    // In production, could add to Redis ban list
    if (process.env.REDIS_URL) {
      redisClient.set(`banned:${req.ip}`, '1', {
        EX: 3600 // 1 hour ban
      });
    }

    res.status(429).json({
