```javascript
const crypto = require('crypto');

const ENCRYPTION_ALGORITHM = 'aes-256-gcm';
const BIT_LENGTH = 256;

// Generate and store encryption key securely
function generateKey() {
  return crypto.randomBytes(BIT_LENGTH / 8);
}

// AES-GCM encryption for sensitive data (authenticated encryption)
function encrypt(text, key) {
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv(ENCRYPTION_ALGORITHM, key, iv);

  let encrypted = cipher.update(text, 'utf8', 'hex');
  encrypted += cipher.final('hex');

  const authTag = cipher.getAuthTag();

  return Buffer.concat([
    iv,
    authTag,
    Buffer.from(encrypted, 'hex')
  ]).toString('base64');
}

// Decryption with validation
function decrypt(base64Data, key) {
  try {
    const decoded = Buffer.from(base64Data, 'base64');
    const iv = decoded.slice(0, 12);
    const authTag = decoded.slice(12, 16);
    const encrypted = decoded.slice(16);

    const decipher = crypto.createDecipheriv(
      ENCRYPTION_ALGORITHM, key, iv
    );
    decipher.setAuthTag(authTag);

    let decrypted = decipher.update(encrypted);
    decrypted = Buffer.concat([decrypted, decipher.final()]);

    return decrypted.toString('utf8');
  } catch (err) {
    throw new Error('Decryption failed - data may be corrupted or tampered');
  }
}
