// Secure application example with security best practices
const express = require('express');
const helmet = require('helmet');
const csrf = require('csurf');
const { body, param, query, validationResult } = require('express-validator');
const crypto = require('crypto');
const path = require('path');

const app = express();

// ============================================
// 1. Security Headers & Middleware
// ============================================
app.use(helmet()); // Sets secure HTTP headers

app.use((req, res, next) => {
  // Additional security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Content-Security-Policy', "default-src 'self'; script-src 'self' 'unsafe-inline'");

  // Rate limiting (requires external middleware)
  next();
});

app.use(express.json({ limit: '10kb' })); // Limit request payload size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================
// 2. Authentication Middleware
// ============================================
const jwt = require('jsonwebtoken');

// ✅ Generate secure secrets at startup
const JWT_SECRET = process.env.JWT_SECRET || crypto.randomBytes(64).toString('hex');

// Rate limiting store (Simple in-memory for demo)
const rateLimitMap = new Map();

const rateLimit = (windowMs = 15 * 60 * 1000, maxRequests = 100) => {
  return (req, res, next) => {
    const key = req.ip;
    const now = Date.now();

    if (!rateLimitMap.has(key)) {
      rateLimitMap.set(key, { count: 0, resetTime: now + windowMs });
    }

    const record = rateLimitMap.get(key);

    if (now > record.resetTime) {
      record.count = 0;
      record.resetTime = now + windowMs;
    }

    record.count++;

    if (record.count > maxRequests) {
      return res.status(429).json({
        error: 'Too many requests',
        retryAfter: Math.ceil((record.resetTime - now) / 1000 / 60)
      });
    }

    next();
  };
};

const authenticateToken = async (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const user = jwt.verify(token, JWT_SECRET);
    req.user = user;
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// ============================================
// 3. Express Validations
// ============================================
// Input validators for /health endpoint
app.get('/health',
  (req, res) => {
    // No validation needed - only basic health check
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    });
  }
);

// Input validators for /users list
app.get('/users',
  authenticateToken,
  rateLimit(),
  (req, res) => {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);

// Input validators for /users/:id
app.get('/users/:id',
  authenticateToken,
  rateLimit(),
  param('id')
    .isInt({ min: 1 }).withMessage('User ID must be a positive integer'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Simulate database query with safe parameter
    const userId = req.params.id;

    res.json({
      id: parseInt(userId),
      name: 'Test User',
      email: 'test@example.com'
    });
  }
);

// Input validators for /login
app.post('/login',
  body('username')
    .trim()
    .isLength({ min: 3, max: 30 })
    .withMessage('Username must be 3-30 characters'),
  body('password')
    .isLength({ min: 8 })
    .withMessage('Password must be at least 8 characters')
    .matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/)
    .withMessage('Password must contain uppercase, lowercase, and number'),
  async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { username, password } = req.body;

    // ❌ NEVER HARDCODE CREDENTIALS - This is for demo only
    // In production, use a proper authentication provider
    if (username === 'admin' && password === process.env.ADMIN_PASSWORD) {
      const token = jwt.sign(
        { id: 1, username: 'admin', role: 'admin' },
        JWT_SECRET,
        { expiresIn: '1h' }
      );

      res.json({
        token,
        user: {
          id: 1,
          username: 'admin',
          role: 'admin'
        }
      });
    } else {
      res.status(401).json({ error: 'Invalid credentials' });
    }
  }
);

// ============================================
// 4. File Upload Protection (If needed)
// ============================================
app.post('/upload',
  authenticateToken,
  rateLimit(),
  body('filename')
    .matches(/^[a-zA-Z0-9._-]+\.(jpg|jpeg|png|gif)$/i)
    .withMessage('Invalid filename format'),
  body('file').custom((value, { req }) => {
    if (!req.file) {
      throw new Error('File is required');
    }
    // Validate file size (max 5MB)
    if (req.file.size > 5 * 1024 * 1024) {
      throw new Error('File size exceeds 5MB limit');
    }
    return true;
  }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Path validation
    const uploadsDir = path.join(__dirname, 'uploads');
    const safePath = path.join(uploadsDir, req.file.originalname);

    if (!safePath.startsWith(uploadsDir)) {
      return res.status(403).json({ error: 'Invalid file path' });
    }

    // Move file to safe location
    fs.renameSync(req.file.path, safePath);
    res.json({ message: 'File uploaded successfully' });
  }
);

// ============================================
// 5. CSRF Protection (for state-changing endpoints)
// ============================================
const cookieParser = require('cookie-parser');
app.use(cookieParser());
const csrfProtection = csrf({ cookie: { secure: true, sameSite: 'strict', httpOnly: true } });

app.post('/user/delete',
  authenticateToken,
  csrfProtection,
  body('id').isInt({ min: 1 }).withMessage('Invalid user ID'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    res.json({ message: 'User deleted successfully' });
  }
);

// ============================================
// 6. SSRF Protection Example
// ============================================
app.get('/redirect',
  authenticateToken,
  query('url')
    .isURL()
    .withMessage('Invalid URL format'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const url = new URL(req.query.url);

    // Block localhost
    if (url.hostname === 'localhost' || url.hostname === '127.0.0.1') {
      return res.status(403).json({ error: 'Redirect to localhost not allowed' });
    }

    // Block private IP ranges
    const privateIPs = [
      /^10\./,
      /^172\.(1[6-9]|2[0-9]|3[0-1])\./,
      /^192\.168\./,
      /^127\./,
      /^0\./
    ];

    if (privateIPs.some(regex => regex.test(url.hostname))) {
      return res.status(403).json({ error: 'Redirect to private networks not allowed' });
    }

    // Block AWS metadata endpoint
    if (url.hostname === '169.254.169.254') {
      return res.status(403).json({ error: 'Redirect to AWS metadata endpoint not allowed' });
    }

    res.redirect(url.href);
  }
);

// ============================================
// 7. CORS Configuration
// ============================================
const cors = require('cors');

// Configure CORS properly
const allowedOrigins = [
  process.env.CLIENT_URL || 'http://localhost:3000',
  'https://your-allowed-domain.com'
];

app.use(cors({
  origin: (origin, callback) => {
    // Allow requests with no origin (e.g., mobile apps, Postman)
    if (!origin) return callback(null, true);
    if (allowedOrigins.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// ============================================
// 8. Error Handling
// ============================================
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(500).json({ error: 'Internal server error' });
});

// 404 Handler
app.use((req, res) => {
