/**
 * Validates secrets exist and sets defaults only when truly necessary
 */
class SecretManager {
  constructor() {
    this.envVars = {
      JWT_SECRET: this._getRequiredSecret('JWT_SECRET'),
      ADMIN_PASSWORD: process.env.ADMIN_PASSWORD || null,
      DATABASE_URL: process.env.DATABASE_URL || null,
      CLIENT_URL: process.env.CLIENT_URL || 'http://localhost:3000',
      NODE_ENV: process.env.NODE_ENV || 'development',
      PORT: process.env.PORT || 3000
    };

    // ✅ VALIDATION: Check for valid JWT secret in production
    if (this.envVars.NODE_ENV === 'production' && this.envVars.JWT_SECRET.length < 32) {
      throw new Error(
        'JWT_SECRET must be at least 32 characters in production'
      );
    }
  }

  /**
   * Retrieves a required secret that must be set or throws an error
   */
  _getRequiredSecret(envVar) {
    const value = process.env[envVar];

    if (!value) {
      const isProduction = process.env.NODE_ENV === 'production';
      const required = isProduction ? 'REQUIRED' : 'optional (will use secure default)';

      throw new Error(
        `${envVar} ${required}. Please set this environment variable. ` +
        `In development, you can generate it with: node -e "require('crypto').randomBytes(64).toString('hex')"`
      );
    }

    return value;
  }

  /**
   * Validates the password complexity
   */
  validatePassword(password) {
    if (password.length < 8) {
      throw new Error('Password must be at least 8 characters');
    }
    if (!/[a-z]/.test(password)) {
      throw new Error('Password must contain at least one lowercase letter');
    }
    if (!/[A-Z]/.test(password)) {
      throw new Error('Password must contain at least one uppercase letter');
    }
    if (!/\d/.test(password)) {
      throw new Error('Password must contain at least one number');
    }
  }

  /**
   * Generates a cryptographically secure default for development only
   */
  getDevelopmentDefault(key) {
    const defaults = {
      JWT_SECRET: crypto.randomBytes(64).toString('hex'),
      ADMIN_PASSWORD: this._generatePassword()
    };
    return defaults[key];
  }

  _generatePassword() {
    return Math.random().toString(36).slice(-12) +
           Math.random().toString(36).slice(-4).toUpperCase();
  }

  getSecret(key) {
    return this.envVars[key];
  }

  getAllSecrets() {
    return { ...this.envVars };
  }
}

