class EnvironmentLoader {
  constructor(secretsManager) {
    this.secretsManager = secretsManager;
  }

  loadDevelopmentEnv() {
    if (this.secretsManager.getSecret('NODE_ENV') !== 'development') {
      console.warn('⚠️ .env file is configured for development only. Production should use environment variables.');
      return;
    }

    const envPath = path.join(__dirname, '.env');

    if (!fs.existsSync(envPath)) {
      console.warn('⚠️ No .env file found. Generating development secrets:');
      this.secretsManager.envVars.JWT_SECRET = secrets.getDevelopmentDefault('JWT_SECRET');
      this.secretsManager.envVars.ADMIN_PASSWORD = secrets.getDevelopmentDefault('ADMIN_PASSWORD');
      console.log(`   JWT_SECRET: ${this.secretsManager.envVars.JWT_SECRET}`);
      console.log(`   ADMIN_PASSWORD: ${this.secretsManager.envVars.ADMIN_PASSWORD}`);
      return;
    }

    // Load and validate .env file
    this._loadAndValidateEnvFile(envPath);
  }

  _loadAndValidateEnvFile(envPath) {
    const envContent = fs.readFileSync(envPath, 'utf8');
    const lines = envContent.split('\n');

    for (const line of lines) {
      if (!line || line.startsWith('#') || line.trim() === '') {
        continue;
      }

      const [key, ...valueParts] = line.split('=');
      const keyName = key.trim();
      const value = valueParts.join('=').trim();

      if (process.env[keyName]) {
        console.warn(`⚠️ Warning: ${keyName} defined in .env but also in environment - environment value takes precedence`);
      } else {
        process.env[keyName] = value;
      }
    }

    console.log('✅ .env file loaded and validated');
  }
}

