const jwt = require('jsonwebtoken');

/**
 * Rate limiting middleware (server-side)
 */
const rateLimitMap = new Map();
const rateLimit = (windowMs = 15 * 60 * 1000, maxRequests = 100) => {
  return (req, res, next) => {
    const key = req.ip;
    const now = Date.now();

    if (!rateLimitMap.has(key)) {
      rateLimitMap.set(key, { count: 0, resetTime: now + windowMs });
    }

    const record = rateLimitMap.get(key);

    if (now > record.resetTime) {
      record.count = 0;
      record.resetTime = now + windowMs;
    }

    record.count++;

    if (record.count > maxRequests) {
      return res.status(429).json({
        error: 'Too many requests',
        retryAfter: Math.ceil((record.resetTime - now) / 1000 / 60)
      });
    }

    next();
  };
};

/**
 * JWT Authentication Middleware
 */
const authenticateToken = async (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({
      error: 'Authentication required',
      message: 'No token provided. Please login to get an auth token.'
    });
  }

  try {
    const user = jwt.verify(token, secrets.getSecret('JWT_SECRET'));
    req.user = user;
    next();
  } catch (err) {
    return res.status(403).json({
      error: 'Invalid or expired token',
      message: err.message
    });
  }
};

