    .isURL()
    .withMessage('Invalid URL format'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const url = new URL(req.query.url);

    if (url.hostname === 'localhost' || url.hostname === '127.0.0.1') {
      return res.status(403).json({ error: 'Redirect to localhost not allowed' });
    }

    const privateIPs = [
      /^10\./,
      /^172\.(1[6-9]|2[0-9]|3[0-1])\./,
      /^192\.168\./,
      /^127\./,
      /^0\./
    ];

    if (privateIPs.some(regex => regex.test(url.hostname))) {
      return res.status(403).json({ error: 'Redirect to private networks not allowed' });
    }

    if (url.hostname === '169.254.169.254') {
      return res.status(403).json({ error: 'Redirect to AWS metadata endpoint not allowed' });
    }

    res.redirect(url.href);
  }
);

