const express = require('express');
const helmet = require('helmet');
const { body, param, query, validationResult } = require('express-validator');
const crypto = require('crypto');
const path = require('path');
const jwt = require('jsonwebtoken');

const app = express();

// ============================================
// 1. Security-First Secrets Management
// ============================================

class SecuritySecrets {
  constructor() {
    this.validateSecrets();
  }

  /**
   * Validates that required secrets are provided
   * Fails application startup if secrets are missing (especially in production)
   */
  validateSecrets() {
    const envVars = this.getRequiredSecrets();

    // Validate JWT_SECRET - MUST be set
    if (!envVars.JWT_SECRET) {
      this.throwSecretError('JWT_SECRET', 'required');
    }

    // In production, enforce minimum length and complexity
    if (process.env.NODE_ENV === 'production' && envVars.JWT_SECRET.length < 32) {
      throw new Error(
        'JWT_SECRET must be at least 32 characters in production. ' +
        'Generate with: node -e "require(' + "'crypto'" + ').randomBytes(64).toString(' + "'hex'" + ')"'
      );
    }
  }

  throwSecretError(secretName, status) {
    const isProduction = process.env.NODE_ENV === 'production';
    throw new Error(
      `⚠️ ${secretName} is ${status}. ` +
      `Application cannot start without this secure credential. ` +
      `Set it in your environment before running the application. ` +
      `${isProduction ? '' : '(Generate with: node -e "require('\''crypto'\'').randomBytes(64).toString('\''hex'\'')"')}`
    );
  }

  /**
   * Ensure secrets are loaded securely
   * Uses a cache to prevent redundant secret lookups
   */
  getSecret(secretName) {
    // Secret validation performed on construction
    // Secrets are always strings from environment, never generated
    return process.env[secretName];
  }

  getRequiredSecrets() {
    return {
      JWT_SECRET: process.env.JWT_SECRET,
      PORT: process.env.PORT || 3000,
      NODE_ENV: process.env.NODE_ENV || 'development',
      ADMIN_PASSWORD: process.env.ADMIN_PASSWORD || null, // Optional for demo
      DATABASE_URL: process.env.DATABASE_URL || null
    };
  }

  getAllSecrets() {
    return { ...this.getRequiredSecrets() };
  }
}

// Initialize secrets with strict validation
let secrets;
try {
  secrets = new SecuritySecrets();
  console.log('✅ Secrets validation passed');
} catch (error) {
  console.error('❌ Application startup secure validation failed:', error.message);
