  console.error('Error:', err);
  if (IS_PRODUCTION) {
    res.status(500).json({
      error: { message: 'Internal server error' }
    });
  } else {
    res.status(500).json({ error: err.message, stack: err.stack });
  }
});

app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
});
```

