// Additional security headers
app.use((req, res, next) => {
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Permissions-Policy',
    'geolocation=(), microphone=(), camera=(), payment=()'
  );
  next();
});
```

---

### 5. ⚠️ CROSS-SITE SCRIPTING VULNERABILITY - CWE-79

**Severity:** High
**OWASP Top 10:** A03:2021 - Injection → Cross-Site Scripting

**Issue:** Email addresses in response data are not sanitized.

**OWASP Impact:**
- Email addresses exposed could be harvested
- Could be injected into malicious emails
- Potential social engineering via encoded emails

**Recommendation:**

```javascript
// Sanitize function to prevent XSS
const sanitize = (input) => {
  if (typeof input !== 'string') return input;
  return input
    .replace(/[<>"'&]/g, (char) => {
      const escapeMap = {
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;',
        '&': '&amp;'
      };
      return escapeMap[char] || char;
    });
};

// Secure endpoint with input sanitization
app.get('/users', authenticateToken, (req, res) => {
  const sanitizedUsers = users.map(user => ({
    id: user.id,
    name: sanitize(user.name),
    email: sanitize(user.email)
  }));

  res.json(sanitizedUsers);
});
```

---

### 6. ⚠️ NO QUERY INJECTION PROTECTION

**Severity:** Medium
**OWASP Top 10:** A03:2021 - Injection

**Issue:** No parameterization or query sanitization for any dynamic inputs.

**Recommendation:**

```javascript
// Express with built-in parameterization
app.get('/users/search', authenticateToken, [
  query('term').exists().trim().toLowerCase().escape().withMessage('Search term required'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be 1-100')
], (req, res) => {
  const errors = expressValidator.validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const searchTerm = req.query.term;
  const limit = parseInt(req.query.limit);

  // Express handles parameterization automatically for ?= syntax
  const results = users.filter(user =>
    user.name.toLowerCase().includes(searchTerm) ||
    user.email.toLowerCase().includes(searchTerm)
  ).slice(0, limit);

  res.json(results);
});
```

---

### 7. ⚠️ EXPOSURE OF STATIC DATA

**Severity:** Medium
**OWASP Top 10:** A01:2021 - Broken Access Control

**Issue:** Sample user data including emails is exposed without any access control.

**Recommendation:**

```javascript
// Remove PII from public returns
app.get('/users', authenticateToken, (req, res) => {
  // Return user information without sensitive PII
  const publicUsers = users.map(user => ({
    id: user.id,
    name: user.name,
    emailStatus: user.email ? 'visible' : 'internal-only'
  }));

  res.json(publicUsers);
});

// Create internal endpoint for full data
app.get('/users/:id/details', authenticateToken, [
  param('id').isInt({ min: 1 })
], (req, res) => {
  const errors = expressValidator.validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const user = users.find(u => u.id === parseInt(req.params.id));
  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  res.json(user);
});
```

---

### 8. ⚠️ CRYPTOGRAPHY WEAKNESS - CWE-327 Potential

**Severity:** Medium
**OWASP Top 10:** A02:2021 - Cryptographic Failures

**Issue:** No password hashing or cryptographic security implemented.

**Recommendation:**

```javascript
const crypto = require('crypto');

// Secure password hashing (example function)
const hashPassword = async (password) => {
  return new Promise((resolve, reject) => {
    crypto.randomBytes(16, (err, salt) => {
      if (err) return reject(err);
      crypto.pbkdf2(
        password,
        salt,
        100000,
        64,
        'sha512',
        (err, derivedKey) => {
          if (err) return reject(err);
          resolve({
            salt: salt.toString('hex'),
            hash: derivedKey.toString('hex')
          });
        }
      );
    });
  });
};

// Or use bcrypt for production
const bcrypt = require('bcrypt');

const hashPassword = (password) => bcrypt.hash(password, 10);
const verifyPassword = (password, hash) => bcrypt.compare(password, hash);
```

