# Security Review of app.js

## Executive Summary
The current implementation has **no authentication/authorization**, **no rate limiting**, **no input validation**, and **serves data without sanitization**. This results in **CRITICAL security vulnerabilities** based on OWASP Top 10.

---

## Critical Vulnerabilities

### 1. [INFORMATION DISCLOSURE] Sensitive Data Exposure (CWE-200)
**Severity: HIGH**

The `/users` endpoint returns internal data including email addresses, which could be used for phishing or social engineering attacks.

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Recommendation:**
```javascript
// Option 1: Remove sensitive data
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

// Option 2: Mask sensitive data
app.get('/users', (req, res) => {
  const maskedUsers = users.map(user => ({
    id: user.id,
    name: user.name,
    email: maskEmail(user.email) // custom function to mask email
  }));
  res.json(maskedUsers);
});

function maskEmail(email) {
  const [local, domain] = email.split('@');
  return `${local.slice(0, 2)}***@${domain}`;
}
```

---

### 2. [INSECURE DESIGN] Broken Access Control (CWE-284)
**Severity: CRITICAL**

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]); // No authentication required
});
```

**Issue:** Anyone can access user data without any authentication.

**Recommendation:**
```javascript
const jwt = require('jsonwebtoken');

// Middleware for authentication
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

// Protect endpoints
app.get('/users', authenticateToken, (req, res) => {
  // If you only want admins to see emails:
  if (req.user.role !== 'admin') {
    return res.json(users.map(u => ({ id: u.id, name: u.name })));
  }
  res.json(users);
});
```

---

### 3. [ISO/OWASP] Broken Access Control: Improper Authorization
**Severity: HIGH**

Same as #2 - no authorization levels implemented.

**Recommendation:**
```javascript
function requireRole(requiredRole) {
  return (req, res, next) => {
    if (!req.user || req.user.role !== requiredRole) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
}

// Usage
app.get('/admin/users', authenticateToken, requireRole('admin'), (req, res) => {
  // Only admins can see this endpoint
});
```

---

### 4. [INJECT] Injection Vulnerabilities (CWE-89, CWE-79)
**Severity: MEDIUM-HIGH**

While there are no injection points in the current code, if you add dynamic routes, you could expose XSS and SQL injection:

**Recommended Input Validation Pattern:**
```javascript
// Security middleware
const { body, param, validationResult } = require('express-validator');

const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

app.get('/user/:id', [
  param('id').isInt({ min: 1 }).withMessage('User ID must be a positive integer')
], validateRequest, (req, res) => {
  const userId = req.params.id;
  res.json(`Fetching user with ID: ${userId}`);
});

app.post('/create-user', [
  body('email').isEmail().normalizeEmail().withMessage('Invalid email format'),
  body('name').isString().trim().isLength({ min: 2, max: 50 }).withMessage('Name must be 2-50 chars'),
  body('password').isLength({ min: 8 }).matches(/[A-Z]/).matches(/[0-9]/)
    .withMessage('Password must be at least 8 chars with uppercase and number')
], validateRequest, (req, res) => {
  // Safe to use req.body property as input has been validated
  const { email, name } = req.body;
  // Proceed with user creation
});
```

---

### 5. [INSECURE] Broken Authentication (CWE-306)
**Severity: CRITICAL**

No password hashing, authentication tokens, or password policies defined.

**Recommendation:**
```javascript
const bcrypt = require('bcrypt');
const saltRounds = 10;

app.post('/login', async (req, res) => {
  const { email, password } = req.body;

  // Validate input
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  try {
    const user = await User.findOne({ email });
    if (!user || !passwordMatch) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const token = jwt.sign(
      { userId: user.id, email: user.email, role: user.role },
      process.env.JWT_SECRET,
      { expiresIn: '1h' }
    );

    res.json({ token, email: user.email });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Password hashing
const hashedPassword = await bcrypt.hash(password, saltRounds);
const passwordMatch = await bcrypt.compare(password, hashedPassword);
```

---

### 6. [DOS] Denial of Service Potential (CWE-400)
**Severity: MEDIUM**

If you add endpoints that handle user input, they could be vulnerable to DoS via long inputs.

**Recommendation:**
```javascript
// Input length limit middleware
app.use(express.json({ limit: '1mb'})); // Configure request body size
app.use(express.urlencoded({ extended: false, limit: '1mb'}));

// Rate limiting
const rateLimit = require('express-rate-limit');

const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests from this IP' }
});

const sensitiveLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
