## Phase 2: Authentication Implementation

### 3. Add Authentication Middleware

**Current Code:** None

**Remediation:**
```javascript
// Install: npm install jsonwebtoken bcrypt

const express = require('express');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');
const app = express();
app.use(express.json());

// JWT authentication middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // In production, use environment variable for secret
  const SECRET_KEY = process.env.JWT_SECRET || 'fallback-secret-change-in-production';

  jwt.verify(token, SECRET_KEY, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user; // Attach user info to request
    next();
  });
}

// Protected route example
app.get('/users', authenticateToken, (req, res) => {
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

// Login endpoint (example)
app.post('/login', (req, res) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: 'Username and password required' });
  }

  // In production, fetch user from database
  const user = { id: 1, username: username, role: 'user' };

  // Generate token (hmac512 for better security than default)
  const token = jwt.sign({ userId: user.id, username: user.username },
                         process.env.JWT_SECRET || 'fallback-secret',
                         { expiresIn: '1h' });

  res.json({ token });
});

module.exports = app;
```

**Security Benefit:**
- Prevents unauthorized access to protected endpoints
- Implements token-based authentication
- Includes proper error handling

