// ========================================================
// SECURE APPLICATION - Security Hardened Version
// ========================================================

const express = require('express');
const helmet = require('helmet');
const session = require('express-session');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const mon = require('express-validator');

// ========================================================
// 1. SECURITY MIDDLEWARE CONFIGURATION
// ========================================================

const app = express();

// HSTS - Force HTTPS (requires HTTPS first or set production)
app.use(helmet({
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },
  noSniff: true,
  ieNoOpen: true,
  firefoxVersion: true,
  frameguard: { action: 'deny' },
  xssFilter: true,
  hidePoweredBy: true,
  noCache: true,
}));

// Body parsing with size limits (prevent DoS)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ========================================================
// 2. CRYPTOGRAPHIC PRODUCTION SECRET (Never in git)
// ========================================================
// IMPORTANT: Set this in environment variable at production!
const APP_SECRET = process.env.APP_SECRET || 'CHANGE_ME_IN_PRODUCTION';
if (process.env.NODE_ENV === 'production') {
  console.warn('⚠️  WARNING: Ensure APP_SECRET is set in environment variables!');
}
if (APP_SECRET === 'CHANGE_ME_IN_PRODUCTION') {
  console.error('❌ CRITICAL: APP_SECRET must be changed for production!');
  process.exit(1);
}

// ========================================================
// 3. CSRF PROTECTION
// ========================================================
const csrf = require('csurf');
const csrfProtection = csrf({ 
  cookie: { 
    httpOnly: true, 
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    maxAge: 3600000 // 1 hour
  } 
});

// Application-level CSRF protection for all routes
app.use(csrfProtection);

app.get('/api/anti-csrf', (req, res) => {
  res.json({ csrfToken: req.csrfToken() });
});

// ========================================================
// 4. ROUTE PROTECTION WITH AUTHENTICATION
// ====================================================

// Ensure no unauthenticated access to routes below
function requireAuth(req, res, next) {
  // Check for JWT token in Authorization header
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  try {
    const decoded = jwt.verify(token, APP_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid or expired token' });
