### SOLUTION 3: Vault Agent Sidecar (Best for Kubernetes)

```javascript
// app.js with Vault Agent sidecar
async function getVaultToken() {
  const fs = require('fs');
  const tokenPath = process.env.VAULT_TOKEN_PATH || '/tmp/vault-token';

  // Sidecar writes token to file only when mounted
  return fs.readFileSync(tokenPath, 'utf8').trim();
}

async function getVaultSecret(path) {
  const vault = require('node-vault')({
    vaultAddr: process.env.VAULT_ADDR,
    token: await getVaultToken(),
  });

  try {
    const secret = await vault.read({ path });
    return secret.data;
  } catch (error) {
    if (error.statusCode === 403) {
      console.warn('Vault access denied - token likely invalid');
    }
    throw error;
  }
}

// Usage:
