    const secrets = await getVaultSecret('secret/production/app');

    console.log('🔒 Secrets loaded from Vault');
    console.log('🎯 APP_SECRET:', process.env.APP_SECRET);
  } catch (err) {
    console.error('❌ Critical: Secret retrieval failed:', err.message);
    process.exit(1);
  }
})();
```

