#### Azure Key Vault
```javascript
const { SecretClient } = require('@azure/keyvault-secrets');
require('dotenv').config();

const credential = require('@azure/identity').DefaultAzureCredential();

async function getSecretFromAzureKV(secrets) {
  const secretClient = new SecretClient(
    process.env.AZURE_KEY_VAULT_URL,
    credential
  );

  const promises = secrets.map(s => {
    const [name] = s.split('/');
    return secretClient.getSecret(name);
  });

  const results = await Promise.all(promises);
  const secretMap = {};

  results.forEach((result, index) => {
    secretMap[secrets[index].slice(1)] = result.value.value;
  });

  return secretMap;
}

// Usage:
async function loadApp() {
  const secrets = await getSecretFromAzureKV([
    '/production/app-secret',
    '/production/db-password',
    '/production/api-key',
  ]);

  const APP_SECRET = secrets['production/app-secret'];
  // Rest of app config...
}
```

