  const status = APP_SECRET ? 'ok' : 'failed';

  res.json({
    status,
    appSecret: secretCheck,
    environment: process.env.NODE_ENV,
  });

  if (APP_SECRET) {
    logger.info('✅ Application secrets validated', { secretCheck });
  } else {
    logger.error('⚠️ Application secrets MISSING - critical issue', { status });
  }
});

// ========================================================
// 7. PROTECTED ROUTES
// ========================================================

// Authentication required
app.get('/users', verifyToken, async (req, res) => {
  // Headers contain user info, do not include in response
  logger.info(`User accessing /users: ${req.user.email} (IP: ${req.ip})`);

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.get('/users/:id', verifyToken, async (req, res) => {
  const { id } = req.params;

  // Input validation
  if (!/^\d+$/.test(id)) {
    return res.status(400).json({ error: 'Invalid user ID format' });
  }

  logger.info(`User fetching user ${id}: ${req.user.email}`);

  res.json({
    id: parseInt(id),
    name: 'Bob',
    email: 'bob@example.com',
