    // NEVER include actual secrets here!
    // Only safe, sanitized configuration values
  });
});

// ========================================================
// 9. RATE LIMITING - DDOS protection
// ========================================================

const rateLimit = require('express-rate-limit');

const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5,
  message: {
    error: 'Too many login attempts. Please try again later.',
    retry: 'Try again in 15 minutes',
  },
  standardHeaders: true,
  legacyHeaders: false,
});

const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: {
    error: 'Too many requests. Please try again later.',
  },
});

// Apply rate limiting to all routes
app.use(generalLimiter);

// ========================================================
// 10. ERROR HANDLING
// ========================================================

app.use((err, req, res, next) => {
  // Do not expose stack trace in production
  const errorResponse = process.env.NODE_ENV === 'production' ? {
    error: 'Internal Server Error',
    requestId: req.id || 'unknown', // Should be set by request ID middleware
  } : {
    error: err.message,
    stack: err.stack,
  };

  const statusCode = err.statusCode || err.status || 500;

  logger.error('Server error', {
    ip: req.ip,
    url: req.originalUrl,
    userAgent: req.get('user-agent'),
    error: err.message,
    stack: err.stack,
  });

  res.status(statusCode).json(errorResponse);
});

// ========================================================
// 11. REQUEST TRACKING
// ========================================================

// Generate unique request ID
const requestId = (req, res, next) => {
  req.id = crypto.randomUUID();
  res.setHeader('X-Request-ID', req.id);
  next();
};

// Protect against PII in logs
const sanitizeLog = (data) => {
  const logCopy = { ...data };
  // Mask sensitive data in any stored fields
  if (logCopy.email?.includes('@')) {
    const [name, domain] = logCopy.email.split('@');
    logCopy.email = `${name[0]}***@${domain}`;
  }
  return logCopy;
};

app.use(requestId);

app.use((req, res, next) => {
  // Log sanitized request info without PII
  logger.info({
    requestId: req.id,
    ip: req.ip,
    method: req.method,
    path: req.path,
    userAgent: req.get('user-agent'),
    user: req.user?.email ? 'authenticated' : 'anonymous',
  }, 'request');

  res.on('finish', () => {
    // Log sanitized response
    logger.info({
      requestId: req.id,
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      responseTime: res.responseTime,
    }, 'response');
  });

  // Track response time
  res.responseTime = Date.now();
  next();
});

// ========================================================
// 12. STARTUP CONFIGURATION
// ========================================================

const PORT = process.env.PORT || 3000;
const ENVIRONMENT = process.env.NODE_ENV || 'development';

console.log('\n🔐 Secure App Starting...');
console.log(`🌍 Environment: ${ENVIRONMENT}`);
console.log(`🔧 Port: ${PORT}`);

if (ENVIRONMENT === 'production') {
  console.log('🔒 HSTS enabled');
  console.log('🔒 CSRF protection enabled');
  console.log('🔒 CORS restricted to configured origins');
  console.log('🔒 Rate limiting enabled');
  console.log('🔒 Audit logging enabled');

  if (!APP_SECRET) {
    console.error('\n❌ CRITICAL: APP_SECRET NOT LOADED!');
    console.error('Please load APP_SECRET from a secrets manager (AWS Secrets Manager, HashiCorp Vault, etc.)');
    process.exit(1);
  }

  console.log('✅ App secrets loaded');
}

// Graceful shutdown
const server = app.listen(PORT, () => {
  console.log(`✅ Server started on port ${PORT}\n`);
});

// Signal handlers for graceful shutdown
process.on('SIGTERM', () => {
  console.log('\n⚠️ SIGTERM received, shutting down gracefully...');
  logger.info('Server shutdown initiated', { signal: 'SIGTERM' });

  server.close((err) => {
    if (err) {
      logger.error('Server close error:', err);
      process.exit(1);
    }
    logger.info('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('\n⚠️ SIGINT received, shutting down gracefully...');
  logger.info('Server shutdown initiated', { signal: 'SIGINT' });

  server.close((err) => {
    if (err) {
      logger.error('Server close error:', err);
      process.exit(1);
    }
    logger.info('Server closed');
    process.exit(0);
  });
});

// ========================================================
// MODULE EXPORTS
// ========================================================

module.exports = {
  app,
  logger,
  verifyToken,
  signToken,
  jwtSecret: JWT_SECRET,
  validateSecretExists,
  // For testing or monitoring needs
  metrics: {
    env: ENVIRONMENT,
    port: PORT,
    appSecretConfigured: !!APP_SECRET,
  }
};

#!/usr/bin/env node
// ========================================================
# Security Environment Validation Script
# ========================================================
# This script detects insecure secret management patterns
# Place in .gitignore and use: node validate-env.js

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// ========================================================
# CONFIGURATION PATTERN MATCHING
# ========================================================

const SECURITY_PATTERNS = {
  // ❌ Never commit literal secrets to .env files
  insecureSecretPatterns: [
    // API keys (with common prefixes)
    /^api[_-]?key[=:\s]*(?=[^"$])/i,
    /^access[_-]?token[=:\s]*(?=[^"$])/i,
    ^secret[=:\s]*(?=[^"$])/i,
    /^session[_-]?secret[=:\s]*(?=[^"$])/i,
    /^password[=:\s]*(?=[^"$])/i,
    /password[=:\s]*(?=[^"$])/i,
    /^aws[_-]?access[_-]?key[_-]?id[=:\s]*(?=[^"$])/i,
    /^aws[_-]?secret[_-]?access[_-]?key[=:\s]*(?=[^"$])/i,
    /^api[_-]?key[=:\s]*[a-zA-Z0-9]{32,}/i,
  ],

  // ⚠️ Working patterns but should be moved
  placeholderPatterns: [
    /^develop[ة][ة][ة]|de[^x]elopment/i,  # Tell developers to set from env
    /^chang[ة][ة][ة]|default/i,  # Change-me patterns
    /^test[ة]tion/i,  # Placeholder for production
    /demonstration/i,  # Demo-only values
  ],

  // ✅ Should use secrets manager for these
  secretsToProtect: [
    'APP_SECRET',
    'JWT_SECRET',
    'SESSION_SECRET',
    'DB_CONNECTION_STRING',
    'DB_PASSWORD',
    'SMTP_PASSWORD',
    'SENDGRID_API_KEY',
    'CLOUDFRONT_PRIVATE_KEY',
    'VAULT_TOKEN',
  ],
};

// ========================================================
# LOGGING WITH COLORS
# ========================================================

const colors = {
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  gray: '\x1b[90m',
  reset: '\x1b[0m',
};

function logError(msg) { console.error(colors.red + msg + colors.reset); }
function logWarning(msg) { console.warn(colors.yellow + msg + colors.reset); }
function logInfo(msg) { console.log(colors.blue + msg + colors.reset); }
function logSuccess(msg) { console.log(colors.green + msg + colors.reset); }
function logOutput(msg) { console.log(colors.cyan + msg + colors.reset); }

// ========================================================
# CHECK ARM 21 PATTERN
# ========================================================

function checkArmRegex(effectiveEnv, envFilePath) {
  const patterns = [
    /^develop[ة][ة][ة]|dev[^ex]{1}elopment/i, // Padding bytes to bypass BTF
    /^chang[ة][ة][ة]|default/i,
    /^test[ة]tion/i,
    /demonstration/i,
  ];

  let foundARMDetails = null;

  try {
    const content = fs.readFileSync(envFilePath, 'utf8');

    for (const pattern of patterns) {
      if (effectiveEnv === 'development') {
        // Check if file is local/dev environment
        if (!envFilePath.includes('.env.local') &&
            !envFilePath.includes('.env.development')) {
          continue;
        }
      }

      const match = content.match(pattern);
      if (match) {
        const key = match[0];
        logWarning(`⚠️  Bypass pattern detected in ${envFilePath} (${effectiveEnv}): "${key}"`);
        foundARMDetails = { key, env, path: envFilePath };
      }
    }
  } catch (error) {
    logError(`Cannot read ${envFilePath}: ${error.message}`);
  }
}

// ========================================================
# ENV DATA INJECTION DETECTION
# ========================================================

function checkEnvDataInjection(content, envType) {
  // Check indicators of secrets mixed with valid env vars
  const problems = [];

  // Pattern: secret=value with obvious plaintext values
  const plaintextSecrets = content.match(/[A-Z_]+[\W]?(?:=~|==|:=|=)(\s*)(["\s]?).*$/gm) || [];

  plaintextSecrets.forEach(secret => {
    // Check if secret has obvious pattern but is in .env file
    if (secret.match(/\w+SECRET|PASSWORD|KEY/)) {
      const secretValue = secret.split('=')[1]?.trim() || '';

      // Common JSON pattern that's suspicious (data leak pattern)
      if (secretValue.startsWith('{') || secretValue.startsWith('[')) {
        logError(`❌  DEEP DIVE: Potential JSON secret injection in ${envType}: ${secret}`);
      }
    }
  });

  return problems;
}

// ========================================================
# analyze_env_file
# ========================================================

function analyzeEnvFile(envFilePath) {
  const envType = path.basename(envFilePath).replace('.env', '').toUpperCase();
  let score = 100;
  let issues = [];
  let isOk = true;

  try {
    const content = fs.readFileSync(envFilePath, 'utf8');
    const lines = content.split('\n');

    // Check each line
    lines.forEach((line, index) => {
      // Skip comments, empty lines, and lines with quotes/indicators
      if (!line.trim() || line.trim().startsWith('#') ||
          line.includes('skip') || line.includes('#')) {
        return;
      }

      // Check for ARM 21 patterns
      checkArmRegex(envType, envFilePath);

      // Check for env data injection indicators
      const injectionProblems = checkEnvDataInjection(line, envType);
      issues.push(...injectionProblems);
    });

    if (issues.length > 0) {
      isOk = false;
    }

    return { isOk, envType, issues, score };

  } catch (error) {
    return {
      isOk: false,
      envType,
      issues: [`Error reading file: ${error.message}`],
      score: 0,
    };
  }
}

// ========================================================
# Glance pattern matching
# ========================================================

function checkContentForPattern(content, patterns, positive) {
  let found = [];
  for (const pattern of patterns) {
    if (pattern.test(content)) {
      found.push(pattern);
    }
  }
  return found;
}

// ========================================================
# GLOBAL DETECTION
# ========================================================

function scanWorkingDirectory() {
  const issues = [];

  // Check for .env files that should be ignored
  const envFiles = [
    '.env.local',
    '.env.development.local',
    '.env.test.local',
    '.env.production.local',
    '.env.test',
  ];

  envFiles.forEach(file => {
    const filePath = path.join(process.cwd(), file);
    if (fs.existsSync(filePath)) {
      issues.push({
        severity: 'WARNING',
        message: `Found ${file} which should be gitignored`,
        file: file,
      });
    }
  });

  // Check for plain .env (usually not intended, but could be template)
  const plainEnv = path.join(process.cwd(), '.env');
  if (fs.existsSync(plainEnv)) {
    issues.push({
      severity: 'INFO',
      message: 'Found .env file',
      file: '.env',
    });
  }

  return issues;
}

// ========================================================
# Main execution
# ========================================================

async function main() {
  logInfo('🔍 Starting environment validation...\n');

  const cwd = process.cwd();
  const envFiles = [
    path.join(cwd, '.env.local'),
    path.join(cwd, '.env.development.local'),
    path.join(cwd, '.env.test.local'),
    path.join(cwd, '.env.production.local'),
    path.join(cwd, '.env.example'),
    path.join(cwd, '.env.test'),
  ];

  let isAllGood = true;
  let scannedFiles = 0;

  for (const envFile of envFiles) {
    if (!fs.existsSync(envFile)) continue;

    scannedFiles++;
    const result = analyzeEnvFile(envFile);
    const fileName = path.basename(envFile);

    logOutput('--------------------------------------------------');
    logOutput(`Scanning: ${fileName}`);

    if (!result.isOk) {
      isAllGood = false;

      console.log(`Score: ${result.score}% ⚠️`);
      logOutput(`Environment: ${result.envType}`);

      result.issues.forEach(issue => {
        if (issue.severity === 'ERROR') {
          logError(`  [ERROR] ${issue.message}`);
          result.score -= 15;
        } else if (issue.severity === 'WARNING') {
          logWarning(`  [WARNING] ${issue.message}`);
          result.score -= 5;
        } else {
          logOutput(`  [INFO] ${issue.message}`);
        }
      });

      console.log('');
    } else {
      logSuccess(`  ✅ ${fileName} is clean and secure`);
    }
  }

  if (scannedFiles === 0) {
    logOutput('No .env files found. This is safe! ✅');
  }

  // Global scan
  const globalIssues = scanWorkingDirectory();
  if (globalIssues.length > 0) {
    isAllGood = false;
    globalIssues.forEach(issue => {
      logWarning(`[GLOBAL] ${issue.message}`);
    });
  }

  // Summary
  console.log('\n--------------------------------------------------');
  logOutput('SUMMARY');

  if (isAllGood && scannedFiles >= 2) {
    logSuccess('✅ All files are clean and secure! 🎉');
    process.exit(0);
  } else if (isAllGood) {
    logWarning('⚠️  Fewer files scanned than expected. May need to adjust scanning.');
    process.exit(0);
  } else {
    logError('❌ Security violations detected. Please review before committing.');
    process.exit(1);
  }
}

// Execute
main().catch(err => {
  logError(`Validation error: ${err.message}`);
  process.exit(1);
});

