## Unified Secret Loading Pattern

```javascript
// secrets-manager.js
const fs = require('fs');
const path = require('path');

class SecretManager {
  constructor() {
    this.secrets = null;
  }

  async load() {
    const environment = process.env.NODE_ENV || 'development';

    switch (environment) {
      case 'production':
        return this.loadFromCloudProvider();
      case 'development':
        return this.loadFromEnvFile();
      case 'test':
        return this.loadFromTestEnv();
      default:
        throw new Error(`Unknown environment: ${environment}`);
    }
  }

  async loadFromCloudProvider() {
    // Option 1: AWS Secrets Manager
    if (process.env.AWS_SECRET_MANAGER_NAME) {
      const AWS = require('aws-sdk');
      const secretsManager = new AWS.SecretsManager();
      const { SecretString } = await secretsManager
        .getSecretValue({ SecretId: process.env.AWS_SECRET_MANAGER_NAME })
        .promise();
      return JSON.parse(SecretString);
    }

    // Option 2: HashiCorp Vault
    if (process.env.VAULT_ADDR) {
      const Vault = require('node-vault');
      const vault = Vault({
        endpoint: process.env.VAULT_ADDR,
        token: process.env.VAULT_TOKEN
      });
      const { data } = await vault.read('secret/data/myapp/production');
      return data.data;
    }

    // Default: fall back to environment with warnings
    console.warn('⚠️  Cloud secrets manager not configured. Using env variables.');
    return this.loadFromEnvFile();
  }

  loadFromEnvFile() {
    // Check for .env file
    if (fs.existsSync('.env.local')) {
      return this.parseEnvFile('.env.local');
    }
    if (fs.existsSync('.env.local.example')) {
      // Template without actual values
      return {};
    }
    return {};
  }

  loadFromTestEnv() {
    // For test environments, check for test-specific secrets
    return {}
  }

  parseEnvFile(filepath) {
    const envContent = fs.readFileSync(filepath, 'utf8');
    const secrets = {};

    envContent.split('\n').forEach(line => {
      if (line.startsWith('#') || !line.includes('=')) return;

      const [key, value] = line.split('=');
      secrets[key] = value.trim();

      // Mask sensitive values in console
      if (key.includes('SECRET') || key.includes('PASSWORD') || key.includes('TOKEN')) {
        console.log(`🔒 Loaded secret: ${key}=***`);
      } else {
        console.log(`✓ Loaded: ${key}`);
      }
    });

    return secrets;
  }

  getSecret(key, defaultValue = undefined) {
    if (this.secrets && this.secrets.hasOwnProperty(key)) {
      return this.secrets[key];
    }
    return process.env[key] || defaultValue;
  }

  getJWTSecret() {
    return this.getSecret('JWT_SECRET');
  }

  getDatabaseURL() {
    return this.getSecret('DATABASE_URL');
  }
}

// Singleton instance
const secretManager = new SecretManager();

module.exports = secretManager;
```

