## Critical Vulnerabilities

### 1. Broken Access Control (A01:2021)
**Severity:** CRITICAL

**Current Code:**
```javascript
const express = require('express');
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Issue:** No authentication or authorization mechanism. Any network visibility can access all endpoints.

**Attacker Scenario:**
1. Port scan discovers service on port 3000
2. `GET /users` returns full user database without credentials
3. Email addresses and user identity exposed

**Solution with Authentication:**
```javascript
const express = require('express');
const jwt = require('jsonwebtoken');
const app = express();

const JWT_SECRET = process.env.JWT_SECRET || 'change_me_in_production';

// Middleware to verify JWT tokens
function verifyToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Protected route
app.get('/users', verifyToken, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Endpoint to get tokens
app.post('/auth/token', (req, res) => {
  const token = jwt.sign({ id: 1, email: 'alice@example.com' }, JWT_SECRET, {
    expiresIn: '1h'
  });
  res.json({ token });
});

app.listen(3000);
```

**Environment Requirement:**
```bash
# .env file (NEVER commit this!)
JWT_SECRET=should_be_at_least_32_characters_long_random_string
```

