## 3 Approaches to Secrets Loading

### Option 1: Process.env + dotenv (Recommended for simpler apps)

**package.json scripts:**
```json
{
  "start:dev": "NODE_ENV=development nodemon app.js",
  "start:prod": "NODE_ENV=production node app.js"
}
```

**app.js:**
```javascript
// ✅ Load environment variables at the top
require('dotenv').config();

const express = require('express');
const app = express();

// ✅ Validate required secrets exist
const requiredSecrets = ['DATABASE_URL', 'JWT_SECRET', 'PORT'];
requiredSecrets.forEach(secret => {
  if (!process.env[secret]) {
    console.error(`❌ Missing required environment variable: ${secret}`);
    process.exit(1);
  }
});

// ✅ Load secrets with default values for dev
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const DATABASE_URL = process.env.DATABASE_URL;
const JWT_SECRET = process.env.JWT_SECRET;

// ✅ Use secrets in code
if (NODE_ENV === 'production') {
  console.log('🔒 Production mode - secrets loaded securely');
} else {
  console.log('🔧 Development mode');
}
```

**Pros:**
- Simple to understand
- Stateless (no external service)
- Works with CI/CD easily

**Cons:**
- Sensitive information in environment files
- Not ideal for large apps

---

### Option 2: AWS Secrets Manager (Secure for cloud apps)

**Installation:**
```bash
npm install @aws-sdk/client-secrets-manager
```

**app.js (AWS Secrets Manager):**
```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Initialize client
const secretsClient = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1'
});

// Function to get secret (with caching)
let cachedSecret = null;
let cacheExpiry = null;

async function getSecret(secretName) {
  const now = Date.now();

  // Return cached secret if still valid (5 minute cache)
  if (cachedSecret && cacheExpiry > now) {
    return cachedSecret;
  }

  try {
    const response = await secretsClient.send(
      new GetSecretValueCommand({ SecretId: secretName })
    );

    const secretString = response.SecretString
      ? JSON.parse(response.SecretString)
      : response.SecretBinary?.toString('utf-8');

    cachedSecret = secretString;
    cacheExpiry = now + (5 * 60 * 1000); // 5 minutes

    return secretString;
  } catch (error) {
    console.error('❌ Failed to get secret:', secretName, error);
    throw error;
  }
}

// Usage in app.js
app.get('/', async (req, res) => {
  const dbConfig = await getSecret('prod/database-config');
  await db.connect(dbConfig);
  // ...
});

app.post('/login', async (req, res) => {
  const jwtConfig = await getSecret('prod/jwt-config');
  // Verify JWT with config
});
```

**Pros:**
- Secrets never stored in code
- No cached secrets in memory
- Auditable access to secrets
- Can rotate secrets without deployments

**Cons:**
- External dependency (AWS)
- Needs proper IAM role/permissions

---

### Option 3: HashiCorp Vault (Enterprise/Cloud-agnostic)

**Installation:**
```bash
npm install hashi-vault
```

**app.js (HashiCorp Vault):**
```javascript
const { VaultClient } = require('hashi-vault');

const vault = new VaultClient({
  // Using env vars for Vault auth
  endpoint: process.env.VAULT_ENDPOINT || 'https://vault.example.com',
  token: process.env.VAULT_TOKEN,
  sslVerification: process.env.VAULT_SKIP_VERIFY === 'true' ? false : true
});

// Authentication (one-time)
async function authenticateVault() {
  await vault.auth.token.login({
    token: process.env.VAULT_TOKEN
  });
}

// Get secret with refresh capability
const dbSecret = await vault.read('secret/data/database');
const jwtSecret = await vault.read('secret/data/jwt');

// Or use automatic refresh
const persistentSecret = await vault.read({
  secret: 'secret/data/database',
  renew: true, // Refreshes token automatically
  renewPeriod: 3600 // Refresh every hour
});

module.exports = { vault };
```

**Pros:**
- Industry standard for secrets
- Built-in rotation
- RBAC/ABAC control
- Audit logging

**Cons:**
- Complex setup
- External dependency
- Requires network access

