```javascript
const expressValidator = require('express-validator');

// Add input validation to routes
app.get('/users', authenticateToken, [
  // Validate query parameters
  expressValidator.query('offset').optional().isInt({ min: 0 }),
  expressValidator.query('limit').optional().isInt({ min: 1, max: 100 }),
  // Validate request format
  expressValidator.body('email').isEmail().normalizeEmail(),
  expressValidator.body('name').trim().notEmpty().isLength({ min: 2, max: 50 }),
], (req, res) => {
  // Check for validation errors
  const errors = expressValidator.validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // Continue with controller logic...
});

// For GET requests, use custom validation
function validateIdParam(req, res, next) {
  const { id } = req.params;
  if (!id || isNaN(id)) {
    return res.status(400).json({ error: 'Invalid ID parameter' });
  }
  next();
}

app.get('/users/:id', authenticateToken, validateIdParam, (req, res) => {
  // Safe to use req.params.id - it's been validated as a number
});
```

